fit_data_path = 'e:\SHARE\Fe\Data\analysis\06_fit_with_J0\Sym4D_cutsAndFits';
% 2 primary fits 1 for 110 and another one for 200 tangential
% directions:
fit_data_file = 'FitEn_cut400ref110_2D_dirGH_dE20_fix_bg_slope.mat';%Externaly 2-exponent fit fixed bg at high momentum.
fit_data_file = 'FitEn_cut400ref200_2D_dirGH_dE20_fix_bg_slope.mat';%Externaly 2-exponent fit fixed bg at high momentum.

if ~exist('fit_resEi400','var')
    %fit_data_file = 'FitEn_cut200_1Dsbg_dirGH_dE20_fix_bg_slope.mat'; % fit 1D background with no Q-slope
    %fit_data_file = 'FitEn_cut200_1D_fit_bg_dirGH_dE20_fix_bg_slope.mat';%Externaly 2-exponent fit fixed bg at high momentum.

    ld = load(fullfile(fit_data_path,fit_data_file));
    if isfield(ld,'fit_resEi400')
        fit_resEi400 = ld.fit_resEi400;
    else
        fit_resEi400 = ld.fit_res;
    end
end
data_path = 'e:\SHARE\Fe\Data\analysis\06_fit_with_J0\sym4D_cutsAndFits';
fit_file = 'multicuts_fit_dataGH_ei400meV.mat';
if ~exist('cuts2fit400','var')
    ld = load(fullfile(data_path,fit_file));
    cuts2fit400 = ld.cuts2fit400;
end

mi = maps_instrument(400,600,'S');
sample=IX_sample(true,[1,0,0],[0,1,0],'cuboid',[0.04,0.03,0.02]);
cl = cuts2fit400.cutsF_list;
for i=1:numel(cl)
    cl{i} = cl{i}.set_instrument(mi);
    cl{i} = cl{i}.set_sample(sample);

    %cuts2fit.cutsS_list{i} = cuts2fit.cutsS_list{i}.set_instrument(mi);
    %cuts2fit.cutsS_list{i} = cuts2fit.cutsS_list{i}.set_sample(sample);
end
cuts2fit400.cut110_sel = cl{1};
cuts2fit400.cut200_sel = cl{2} %[output:0fb3e060]
cuts2fit = cuts2fit400;
fit_res = fit_resEi400;
%%
[Sgnl,J0,G] = plot_SJG_results(fit_res,'g',{'S','J0','gamma'},{[0,2],[20,60],[0,200]}); %[output:69cc7dfd] %[output:8c9bd474] %[output:395c9861]

dE = min(Sgnl.x(2:end)-Sgnl.x(1:end-1)) %[output:18dc3915]
e_min = Sgnl.x(1);

%%
En = 250 %[output:0540dad6]
fit_par = fit_res.all_fit_par(1);
dE_step = fit_par.en_range(2); %original energy transfer step data were binned to. No point in going finer
half_dE = 0.5*(fit_par.en_range(3)-fit_par.en_range(1));
en_idx =  floor((En-e_min)/dE)+1;
%the2Dcuts = cuts2fit.cutsS_list;%(1:2);
%the2Dcuts = {cut(cuts2fit.cut110_sel,[0,0.02,2],[])};%(1:2);
the2Dcuts = {cuts2fit.cut200_sel};

%init_bg_params =
%cellfun(@(par)[par(1),par(3)],init_bg_params,'UniformOutput',false); % bg
%in case of 2-D fitting
%[fit_obj,fit_par,figa,figb]=fit_single_set(the2Dcuts,En,half_dE,dE_step,init_fg_params,init_bg_params,false)
lfit_par = fit_res.all_fit_par(en_idx);
en_range = lfit_par.en_range;
[fit_obj,fit_par,figa,figb]=refit_singleset_peaks(the2Dcuts,en_range,lfit_par,0.35,true,false); %[output:72961297] %[output:5a871211] %[output:46a31ca0] %[output:5e38f989] %[output:9ac016d3] %[output:6b32afb8] %[output:360d72d9]
%%
%fit_res.all_fit_par(en_idx) = fit_par;
%fit_res.all_fit_par(en_idx).p = fit_par.p;
Sgnl.signal(en_idx) = fit_par.p(4);
J0.signal(en_idx) = fit_par.p(6);
G.signal(en_idx) = fit_par.p(3);
plot_SJG_results(fit_res,'g',{'S','J0','gamma'},{[0.5,2],[20,60],[0,200]},{Sgnl,J0,G}); %[output:08a47c26] %[output:54ec55a1] %[output:22903925]

%%
%the2Dcuts = {cut(cuts2fit.cut200_sel,[0,0.02,1],[])};
the2Dcuts = {cuts2fit.cut200_sel};
fit_res2peak = fit_res;
fit_res2peak.all_fit_par = fit_res.all_fit_par(13:end);
[fit_res2peak,Sg,J0,G] = refit_data_around_peaks(the2Dcuts,fit_res2peak,0.35,true); %[output:5df75367] %[output:17d544fc] %[output:2aecb9be] %[output:38a13187] %[output:1f4b54fb] %[output:2c7399fa] %[output:85748c64] %[output:78d333be] %[output:27aae8e0] %[output:2e6c9058] %[output:9fa92291] %[output:83d30702] %[output:73c41c91] %[output:2926ae3d] %[output:93c4caae] %[output:6c43108a] %[output:19e0dbd2] %[output:953a18b1] %[output:1f138037] %[output:3d754188] %[output:7907cbec] %[output:45aa98bb]
%%
%plot_SJG_results(fit_res,'g',{'S','J0','gamma'},{[0,2],[20,60],[0,200]},{Sg,J0,G});
plot_SJG_results(fit_res2peak,'g',{'S','J0','gamma'},{[0,2],[20,60],[0,200]},{Sg,J0,G}); %[output:9dcf0f78] %[output:59aa6ae2] %[output:1d490dd9]
%%
bg_data = extract_bg_par(fit_res2peak.peak_fit_par,5);
pd(bg_data(1));lx(fit_res.peak_fit_par(1).en,fit_res.peak_fit_par(end).en);keep_figure;ly -0.05 0.05 %[output:64aa21c3]
pd(bg_data(2));lx(fit_res.peak_fit_par(1).en,fit_res.peak_fit_par(end).en);keep_figure;ly -0.05 0.05; %[output:229d4d62]

%pd(bg_data(2));lx(fit_res.peak_fit_par(1).en,fit_res.peak_fit_par(end).en);keep_figure;ly -5 5;
%pd(bg_data(4));lx(fit_res.peak_fit_par(1).en,fit_res.peak_fit_par(end).en);keep_figure;ly -10 5;
%%

